<?php
require_once __DIR__.'/../includes/auth.php';$a=require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$note=trim((string)($_POST['note']??''));if(text_length($note)>500){flash('error','Moderation note is too long.');redirect('admin/reports.php');}if(in_array($status,['open','investigating','resolved','dismissed'],true)){db()->prepare('UPDATE reports SET status=?,resolved_by=?,resolution_note=? WHERE id=?')->execute([$status,in_array($status,['resolved','dismissed'],true)?$a['id']:null,$note?:null,$id]);log_activity((int)$a['id'],'report_'.$status,'report',$id,$note);}redirect('admin/reports.php');}
$pg=pagination_window(20,50);$q=db()->prepare('SELECT r.id,r.target_type,r.target_id,r.reason,r.details,r.status,r.created_at,u.name reporter FROM reports r JOIN users u ON u.id=r.reporter_id ORDER BY r.id DESC LIMIT '.($pg['per']+1).' OFFSET '.$pg['offset']);$q->execute();$rows=$q->fetchAll();$hasNext=trim_page_results($rows,$pg['per']);$error=flash('error');release_session_lock();$pageTitle='Reports — Admin';require __DIR__.'/../includes/header.php';?>
<div class="container py-4"><?php include __DIR__.'/_nav.php';?><h1>User reports</h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if(!$rows):?><div class="alert alert-light border">No reports on this page.</div><?php endif;?><?php foreach($rows as $r):?><div class="card border-0 shadow-sm mb-3"><div class="card-body"><div class="d-flex justify-content-between"><b><?=e($r['target_type'])?> #<?=$r['target_id']?></b><span class="badge text-bg-secondary"><?=e($r['status'])?></span></div><div class="small text-muted">Reported by <?=e($r['reporter'])?> · <?=e($r['reason'])?></div><p class="my-2"><?=e($r['details'])?></p><form method="post" class="row g-2"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><div class="col-md-6"><input class="form-control" name="note" maxlength="500" placeholder="Moderation note"></div><div class="col-md-3"><select class="form-select" name="status"><option>investigating</option><option>resolved</option><option>dismissed</option><option>open</option></select></div><div class="col-md-3"><button class="btn btn-primary w-100">Update</button></div></form></div></div><?php endforeach;?><?=pagination_nav($pg['page'],$hasNext)?></div><?php require __DIR__.'/../includes/footer.php';?>
